contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, uint256 mintedAmount, bool freezeFirst) public {
        // bring supply in line so any subsequent reads are consistent
        c.mintToken(address(this), 1); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        c.freezeAccount(target, freezeFirst); if (__ESBMC_reverted()) return;
        c.mintToken(target, mintedAmount); if (__ESBMC_reverted()) return;
        assert(
            c.balanceOf(target) == balBefore + mintedAmount &&
            c.totalSupply() == supplyBefore + mintedAmount &&
            c.frozenAccount(target) == freezeFirst
        );
    }
    receive() external payable {}
}

