pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address target, uint256 mintedAmount, bool freezeFirst) internal {
        try c.mintToken(address(this), 1) {} catch { return; }
        uint256 balBefore;
        try c.balanceOf(target) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        try c.freezeAccount(target, freezeFirst) {} catch { return; }
        try c.mintToken(target, mintedAmount) {} catch { return; }
        assertTrue(c.balanceOf(target) == balBefore + mintedAmount &&
            c.totalSupply() == supplyBefore + mintedAmount &&
            c.frozenAccount(target) == freezeFirst);
    }

    function testFuzz_run(address target, uint256 mintedAmount, bool freezeFirst) public {
